INSERT INTO articles (id, slug, title, intro, details, steps, tips, documents, fees, warning, source, tags, category, status, seo_title, seo_description, last_update)
VALUES ('open-education-turkey-2026',
        'open-education-turkey-2026',
        'التعليم الجامعي المفتوح في تركيا 2026: أناضولو وإسطنبول وأتاتورك — شهادة معترف بها، لكن بلا إقامة طالب',
        'ثلاث جامعات حكومية تحمل نظام التعليم المفتوح في تركيا: الأناضول (AÖF) في إسكي شهير، وإسطنبول (AUZEF)، وأتاتورك (ATA-AÖF) في أرضروم — دراسة عن بُعد بشهادة جامعية رسمية معترف بها من مجلس التعليم العالي YÖK وبكلفة أدنى كثيراً من التعليم النظامي. لكنّ للنظام حدّاً حاسماً يسكت عنه المروّجون وتقوله جامعة الأناضول نفسها بالحرف: طالب المفتوح الأجنبي لا تُصدر له إدارات الهجرة إقامة طالب، ويُطلب منه أصلاً إثبات أساس بقاء قانوني قائم عند التقديم. هذا الدليل يشرح النظام كاملاً — ولمن يصلح فعلاً.',
        '<div style="background:#fff7ed;border:2px solid #ea580c;border-radius:12px;padding:18px 22px;margin:0 0 20px;"><p style="margin:0 0 10px;font-size:17px;"><strong>الحد الذي يُبنى عليه القرار كله</strong></p><p style="margin:0;">التعليم المفتوح <strong>لا يمنحك إقامة طالب</strong> — جامعة الأناضول تنبّه في إعلان قبولها الدولي إلى أن إدارات الهجرة في الولايات لا تُصدر إقامة طالب لطلاب برامج المفتوح، وتطلب منك عند التقديم إثبات إقامة قائمة. ولا يؤسّس المفتوح <a href="/article/work-permit-students">حقّ العمل الطلابي</a> لأن ذلك الحق يقوم على القيد النظامي الحضوري. فالمفتوح لمن <strong>يملك أساس بقاء آخر</strong>: كملك، إقامة عمل أو عائلية، جنسية — لا لمن يبحث عن طريق إلى تركيا.</p></div><h2>ما هو النظام، ومن يحمله؟</h2><p>التعليم المفتوح (Açık Öğretim) نظام جامعي رسمي عن بُعد: مواد ومحاضرات وامتحانات وفق تقويم الجامعة، وشهادة بكالوريوس أو دبلوم متوسط (Önlisans) صادرة عن جامعة حكومية ومعترف بها من YÖK — لا فرق في الاعتماد عن شهادة التعليم النظامي. تحمله ثلاث جامعات:</p><ul><li><strong>جامعة الأناضول — AÖF</strong> (إسكي شهير): الأقدم والأوسع برامج، ومنصتها Anadolum e-Kampüs للمواد والبث والتقييم. (مَن قرأ عن «جامعة إسكي شهير المفتوحة» فالمقصود الأناضول — هي التي في إسكي شهير.)</li><li><strong>جامعة إسطنبول — AUZEF</strong>: كلية التعليم المفتوح والتعليم عن بُعد.</li><li><strong>جامعة أتاتورك — ATA-AÖF</strong> (أرضروم).</li></ul><p>وإلى جانب الجامعي يوجد «الثانوي المفتوح» (Açık Öğretim Lisesi) التابع لوزارة التربية منذ 1992 — نظام آخر لغير خريجي الثانوية، لا تخلط بينهما.</p><h2>كيف يتقدّم الأجنبي؟</h2><p>القبول الدولي في برامج المفتوح يقوم على <strong>امتحان TR-YÖS أو شهادات وامتحانات دولية معترف بها</strong>، عبر نافذة تقديم إلكترونية <strong>تُفتح صيفاً وتُعلن سنوياً</strong> على موقع الجامعة. أيّ الامتحانين يخصّك ومتى — مشروح في <a href="/article/yks-vs-yos-placement-by-schooling-2026">YKS أم YÖS؟</a>. والدراسة بالتركية أساساً (مع برامج محدودة بلغات أخرى تعلنها كل جامعة) — فإن كانت اللغة عائقك فابدأ من <a href="/article/tomer-registration">TÖMER والبديل المجاني</a>.</p><h2>لمن يصلح المفتوح فعلاً؟</h2><ul><li><strong>حامل الكملك أو إقامة قائمة</strong> الذي يعمل ويريد شهادة جامعية دون التزام حضوري — هذه أنسب حالة على الإطلاق.</li><li><strong>الموظف</strong> الذي يريد ترقية أو تخصصاً ثانياً بكلفة منخفضة.</li><li><strong>من فاته قطار الجامعة</strong> ويريد العودة بلا حدّ عمري.</li></ul><p>ولا يصلح لمن يريد: إقامة طالب، أو <a href="/article/work-permit-students">حق العمل الطلابي</a>، أو الحياة الجامعية الحضورية ومختبراتها — فتلك طريقها التعليم النظامي عبر <a href="/article/study-in-turkey-universities-2026">دليل الدراسة في تركيا</a>.</p><h2>بعد التخرج</h2><p>الشهادة تفتح الدراسات العليا داخل تركيا وخارجها بشروط كل برنامج — <a href="/article/masters-phd-turkey-foreigners-2026">دليل الماجستير والدكتوراه</a>. ووثائقك (كشف الدرجات، وثيقة الطالب) تُستخرج من e-Devlet كأي طالب: <a href="/article/transcript-edevlet">الشرح خطوة بخطوة</a>.</p><h2>أسئلة متكرّرة</h2><h3>هل الشهادة «أضعف» من النظامي؟</h3><p>الاعتماد واحد (YÖK) والشهادة رسمية. الفرق في التجربة لا في الورقة — ولدى بعض أصحاب العمل تفضيل للنظامي في تخصصات بعينها؛ وازن بحسب مجالك.</p><h3>أنا خارج تركيا — هل أدرس المفتوح من بلدي؟</h3><p>الدراسة عن بُعد ممكنة تقنياً من أي مكان، والامتحانات وفق ترتيبات الجامعة ومراكزها المعلنة — راجع إعلان القبول الدولي للسنة الجارية قبل أي التزام.</p><h3>هل يمكن التحويل من المفتوح إلى النظامي لاحقاً؟</h3><p>للتحويل بين النظامين قواعد وقيود خاصة في لائحة التحويل وتُطبّقها كل جامعة بإعلاناتها — لا تفترض إمكانيته، واسأل شؤون الطلاب قبل البناء عليه، وطالع <a href="/article/continue-studies-turkey-2026">دليل استكمال الدراسة</a>.</p>',
        ARRAY['حدّد هدفك بصدق: شهادة عن بُعد لمقيمٍ أساساً — لا طريق إقامة إلى تركيا.', 'تحقّق من أساس بقائك القانوني أولاً (كملك، إقامة عمل/عائلية) — سيُطلب عند التقديم.', 'اختر الجامعة والبرنامج من مواقع AÖF أو AUZEF أو ATA-AÖF الرسمية.', 'جهّز TR-YÖS أو شهادة معترفاً بها، وقدّم في النافذة الصيفية المعلنة سنوياً.', 'بعد القبول: فعّل منصة الجامعة (مثل Anadolum e-Kampüs) والتزم تقويم الامتحانات.', 'استخرج وثائقك الدراسية من e-Devlet عند الحاجة — مجاناً وبرمز تحقق.']::text[],
        ARRAY['المفتوح لا يمنح إقامة طالب — بتصريح جامعة الأناضول نفسها لا باجتهادنا.', 'ولا يؤسس حق العمل الطلابي — ذلك للقيد النظامي الحضوري.', 'الأناضول هي جامعة إسكي شهير — لا توجد «جامعة إسكي شهير مفتوحة» مستقلة.', 'الدراسة بالتركية أساساً — لا تصدّق إعلانات «برامج عربية» قبل رؤيتها على موقع الجامعة.', 'الرسوم أدنى كثيراً من الخاصة وتُحدَّث سنوياً — خذها من موقع الجامعة لا من وسيط.', 'الثانوي المفتوح (منذ 1992) نظام وزارة التربية — غير الجامعي المفتوح.']::text[],
        ARRAY['أساس بقاء قانوني قائم (كملك أو إقامة سارية) — يُطلب إثباته عند التقديم', 'نتيجة TR-YÖS أو شهادة/امتحان دولي معترف به', 'جواز سفر ساري وصور بيومترية', 'الشهادة الثانوية مترجمة مصدقة بحسب متطلبات إعلان الجامعة']::text[],
        'رسوم التعليم المفتوح أدنى بوضوح من الجامعات الخاصة وتُعلَن سنوياً على موقع كل جامعة بحسب البرنامج — لا نثبّت رقماً يتقادم؛ خذ الرقم الجاري من إعلان القبول الرسمي للسنة الجارية.',
        'لا تبنِ خطة قدوم إلى تركيا على قبول تعليم مفتوح: لا إقامة طالب له، وإدارة الهجرة ستسألك عن أساس بقائك لا عن قبولك. ومن وعدك بإقامة عبر المفتوح فهو يبيعك وهماً.',
        'إعلانات القبول الدولي لبرامج التعليم المفتوح في جامعة الأناضول (anadolu.edu.tr — ومنها التنبيه الرسمي بعدم إصدار إقامة طالب لطلاب برامج المفتوح وطلب إثبات إقامة قائمة عند التقديم)؛ وأنظمة AUZEF (istanbul.edu.tr) وATA-AÖF (atauni.edu.tr)؛ واعتماد الشهادات من مجلس التعليم العالي YÖK',
        ARRAY['التعليم المفتوح', 'AÖF', 'الدراسة والتعليم', 'الدراسة عن بعد', 'دليل', '2026']::text[],
        'الدراسة والتعليم',
        'approved',
        'التعليم المفتوح في تركيا: الجامعات والتقديم — وحدوده بصراحة',
        'AÖF وAUZEF وATA-AÖF: شهادة حكومية معترف بها عن بُعد وبكلفة أدنى — لكن بلا إقامة طالب وبلا حق عمل طلابي، بتصريح الجامعة نفسها. الدليل الكامل: التقديم بTR-YÖS، ولمن يصلح النظام فعلاً.',
        CURRENT_DATE)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title, intro = EXCLUDED.intro, details = EXCLUDED.details,
    steps = EXCLUDED.steps, tips = EXCLUDED.tips, documents = EXCLUDED.documents,
