INSERT INTO articles (id, slug, title, intro, details, steps, tips, documents, fees, warning, source, tags, category, status, seo_title, seo_description, last_update)
VALUES ('continue-studies-turkey-2026',
        'continue-studies-turkey-2026',
        'استكمال الدراسة الجامعية في تركيا 2026: التحويل من جامعات الخارج — والمادة الملحقة 2 لطلاب بلدان الحرب',
        'بدأتَ دراستك الجامعية في سوريا أو خارجها ثم انقطعت أو انتقلت؟ القانون التركي يعرف طريقين لاستكمالها: التحويل العادي بين المؤسسات وفق لائحة التحويل، والمادة الملحقة الثانية (Ek Madde 2) المضافة عام 2013 التي فتحت باباً خاصاً لمن كانت دراسته في بلد تعصف به حرب — شملت سوريا ومصر أولاً ثم وسّعتها قرارات مجلس التعليم العالي لاحقاً. هذا الدليل يشرح الطريقين بواقعية: ماذا يشترط كلٌّ منهما، وما الأوراق، ومتى تُفتح الأبواب، وما البديل إن أُغلقت.',
        '<div style="background:#ecfdf5;border:2px solid #10b981;border-radius:12px;padding:18px 22px;margin:0 0 20px;"><p style="margin:0 0 10px;font-size:17px;"><strong>الطريقان في سطرين</strong></p><p style="margin:0;"><strong>التحويل العادي</strong> (Yatay Geçiş): بين جامعة معترف بها وأخرى، بمعدلك ومقاعدَ تعلنها كل جامعة. <strong>المادة الملحقة 2</strong> (Ek Madde 2، منذ 2013): باب خاص لمن كان مقيّداً في بلد حربٍ — بمقاعد وشروط تعلنها الجامعات وفق قرارات YÖK. وفي الحالين: <strong>القرار للجنة الجامعة</strong>، ولا وسيط يملك «ضمان تحويل».</p></div><h2>الطريق الأول: التحويل العادي بين المؤسسات</h2><p>تنظّمه «لائحة الانتقال بين برامج الدبلوم المتوسط والبكالوريوس» — تتقدّم من جامعة معترف بها لدى YÖK إلى مقاعد تحويلٍ تعلنها الجامعة التركية بشروطها: معدل ونجاح في المواد، وسنوات متبقية كافية، وأحياناً شرط لغة. الإعلانات تصدر عادة في <strong>تموز/يوليو وآب/أغسطس</strong> قبيل كل عام دراسي على صفحات شؤون الطلاب (Öğrenci İşleri / OİDB) — تابع صفحة كل جامعة تريدها، فالشروط تختلف من جامعة لأخرى.</p><h2>الطريق الثاني: المادة الملحقة 2 — باب بلدان الحرب</h2><p>أُضيفت إلى اللائحة عام 2013 لتتيح لمن كان يدرس في بلد تعصف به حرب أو اضطراب الانتقالَ إلى جامعة تركية دون بعض قيود التحويل العادي. شملت طلبة سوريا ومصر أولاً، ثم وسّعت قرارات YÖK نطاقها في سنوات لاحقة (حتى شملت حالات كالوباء وجامعات التصنيف الأول عالمياً). المهم عملياً:</p><ul><li>كل جامعة <strong>تعلن مقاعدها وشروطها</strong> ضمن هذا الباب في مواسم التحويل — لا يوجد «تقديم مركزي» واحد.</li><li>يلزم إثبات القيد الجامعي السابق: كشف درجات وتوصيف مقررات مترجمة مصدقة.</li><li>لجنة المعادلة (İntibak) في الجامعة تقرّر ما يُحتسب لك من مقررات وسنوات — توقّع إعادة بعض المواد، فالاحتساب الكامل ليس حقاً مكتسباً.</li></ul><h2>ملف الأوراق — ابدأ به قبل الإعلانات لا بعدها</h2><ul><li>كشف درجات رسمي من جامعتك السابقة + توصيف المقررات (Ders İçerikleri) — مترجمة إلى التركية ترجمة محلّفة ومصدقة.</li><li>الشهادة الثانوية وترجمتها — ولمعادلة الشهادات ومساراتها: <a href="/article/diploma-denklik-syrians-arabs-2026">دليل المعادلة YÖK Denklik</a>.</li><li>جواز السفر، وصور بيومترية، ووثيقة قيد إن توفرت.</li><li>سلاسل التصديق بين تركيا وسوريا مشروحة في <a href="/article/document-attestation-turkey-to-syria-students-2026">دليل تصديق الأوراق</a>.</li></ul><h2>وإن أُغلق البابان؟ البديل المشروع</h2><p>من لم يجد مقعد تحويل — أو وجد لجنة المعادلة تُسقط معظم سنواته — يبقى أمامه البدء طالباً جديداً عبر امتحانات القبول: <a href="/article/yks-vs-yos-placement-by-schooling-2026">YKS أم YÖS؟ أيهما يخصّك</a> ثم <a href="/article/after-yos-turkey-university-tercih-application-registration-2026">التقديم والتسجيل بعد اليوس</a>. وقد يكون أسرع فعلياً من انتظار تحويلٍ لا يأتي. والقادم من خارج تركيا يحتاج قبل كل شيء <a href="/article/turkey-study-visa-syrians-2026">تأشيرة الدراسة</a> ثم <a href="/article/student-residence-permit-2026">إقامة الطالب</a>.</p><h2>أسئلة متكرّرة</h2><h3>انقطعت عن الدراسة سنوات — هل ما زال التحويل ممكناً؟</h3><p>الانقطاع الطويل يعقّد الاحتساب ولا يمنعه حكماً — القول الفصل للجنة الجامعة، وكلما طال الانقطاع رجحت كفة البدء من جديد عبر اليوس.</p><h3>هل أحوّل إلى جامعة خاصة أسهل من حكومية؟</h3><p>الخاصة أوسع مقاعد تحويل عادة وأسرع رداً — لكن بشروطها المالية: <a href="/article/private-universities-turkey-2026">دليل الجامعات الخاصة</a>. والمنح طريق ثالث يستحق النظر: <a href="/article/scholarship-turkey-overview">خريطة المنح كاملة</a>.</p><h3>وسيط يعدني بـ«تحويل مضمون» مقابل مبلغ — أصدّقه؟</h3><p>لا. القرار للجنة الجامعة وحدها، ولا صفة لأي وسيط فيه. اقرأ <a href="/article/student-services-companies-turkey">متى تفيدك شركات الخدمات الطلابية ومتى تحذر</a> قبل دفع قرش.</p>',
        ARRAY['اجمع كشف الدرجات وتوصيف المقررات من جامعتك السابقة — أصعب الأوراق فابدأ بها.', 'ترجمة محلّفة وتصديق لكل وثيقة بحسب متطلبات الجامعة المستهدفة.', 'راقب إعلانات التحويل على صفحات شؤون الطلاب في تموز وآب.', 'قدّم للتحويل العادي أو لمقاعد المادة الملحقة 2 بحسب حالتك — ولأكثر من جامعة.', 'انتظر قرار لجنة المعادلة، ولا تلتزم مالياً قبل معرفة ما احتُسب لك.', 'إن أُغلق الباب: اليوس ثم التقديم كطالب جديد — طريق أبطأ اسماً وأسرع فعلاً أحياناً.']::text[],
        ARRAY['القرار دائماً للجنة الجامعة — «التحويل المضمون» الذي يبيعه وسيط لا وجود له.', 'توصيف المقررات وثيقة الاحتساب الأهم — بدونه تُعاد المواد إعادة.', 'المادة الملحقة 2 بابٌ تعلنه كل جامعة على حدة — لا تقديم مركزياً له.', 'قدّم لأكثر من جامعة في الموسم نفسه — المقاعد ضيقة والشروط متباينة.', 'الانقطاع الطويل يميل بالكفة نحو البدء من جديد — احسبها بواقعية.', 'إعلانات الصيف هي المواسم — من فاته آب انتظر عاماً.']::text[],
        ARRAY['كشف درجات رسمي + توصيف مقررات (Ders İçerikleri) مترجمة مصدقة', 'الشهادة الثانوية وترجمتها المحلفة', 'جواز سفر ساري وصور بيومترية', 'وثيقة انفكاك/قيد من الجامعة السابقة إن توفرت']::text[],
        'رسوم دراسة المحوَّل رسومُ الجامعة المستهدفة نفسها (الحكومية أدنى والخاصة بحسب برنامجها) وتُعلن سنوياً — لا نثبت أرقاماً؛ وترجمة الملف وتصديقه كلفة فعلية فاحسبها من البداية.',
        'لا تترك جامعتك الحالية ولا تصرّح بانفكاك قبل قبول مكتوب من الجامعة الجديدة وقرار معادلة واضح — من فعل وجد نفسه بلا مقعد هنا وهناك. وكل من وعدك بتحويل مضمون مقابل مال فهو يبيع ما لا يملك.',
        'لائحة الانتقال بين برامج الدبلوم المتوسط والبكالوريوس في مؤسسات التعليم العالي ومادتها الملحقة الثانية (المضافة 2013 — بدأت بسوريا ومصر ووسّعتها قرارات مجلس التعليم العالي YÖK اللاحقة)؛ وإعلانات التحويل على صفحات شؤون الطلاب في الجامعات (نموذجاً صفحة OİDB بجامعة مرمرة عن نطاق Ek Madde 2)',
        ARRAY['استكمال الدراسة', 'التحويل الجامعي', 'Ek Madde 2', 'الدراسة والتعليم', 'دليل', '2026']::text[],
        'الدراسة والتعليم',
        'approved',
        'استكمال الدراسة في تركيا: التحويل من الخارج والمادة الملحقة 2',
        'طريقان لاستكمال دراستك الجامعية في تركيا: التحويل العادي بمعدلك، والمادة الملحقة 2 (منذ 2013) لطلاب بلدان الحرب. الأوراق، مواسم تموز وآب، لجنة المعادلة — والبديل المشروع إن أُغلق الباب.',
        CURRENT_DATE)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title, intro = EXCLUDED.intro, details = EXCLUDED.details,
    steps = EXCLUDED.steps, tips = EXCLUDED.tips, documents = EXCLUDED.documents,
    fees = EXCLUDED.fees, warning = EXCLUDED.warning, source = EXCLUDED.source,
    tags = EXCLUDED.tags, category = EXCLUDED.category, status = EXCLUDED.status,
    seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description,
    last_update = EXCLUDED.last_update;

-- ─── student-services-companies-turkey ───
INSERT INTO articles (id, slug, title, intro, details, steps, tips, documents, fees, warning, source, tags, category, status, seo_title, seo_description, last_update)
VALUES ('student-services-companies-turkey',
        'student-services-companies-turkey',
        'شركات الخدمات الطلابية في تركيا: ماذا تفعل فعلاً، ومتى تفيدك، وكيف تكشف المبالِغ منها',
        'حول الدراسة في تركيا نشأت سوق كاملة من «شركات الخدمات الطلابية»: قبول جامعي، استقبال من المطار، سكن، أوراق، خصومات. بعضها يقدّم خدمة حقيقية يدفع كلفتها أصلاً تعاقدُ الجامعات الخاصة مع الوكلاء — وبعضها يبيعك ما تحصل عليه مجاناً بنفسك، أو يعدك بما لا يملكه أحد. هذا الدليل لا يرشّح شركة بعينها ولا يذمّها: يعطيك المسطرة — ما المجاني رسمياً، وأين يكون للوسيط قيمة حقيقية، وما علامات الخطر التي تقطع الطريق على الندم.',
        '<div style="background:#eff6ff;border:2px solid #3b82f6;border-radius:12px;padding:18px 22px;margin:0 0 20px;"><p style="margin:0 0 10px;font-size:17px;"><strong>قاعدة الصفر قبل أي عرض</strong></p><p style="margin:0;">هذه القنوات <strong>مجانية رسمياً ولا تحتاج وسيطاً</strong>: التقديم المباشر للجامعات الحكومية عبر بواباتها، و<a href="/article/scholarship-turkiye-burslari">منحة الحكومة التركية</a> (التقديم عليها مجاني بالكامل عبر موقعها الرسمي)، واستكشاف البرامج عبر منصة YÖK Atlas، والتقديم لبرامج <a href="/article/open-education-turkey-2026">التعليم المفتوح</a> من مواقع الجامعات. أيّ عرض يبدأ بتقاضي رسم عن واحدة من هذه فقد كشف نفسه.</p></div><h2>ماذا تفعل هذه الشركات — بلا تجميل ولا تبخيس</h2><ul><li><strong>القبول في الجامعات الخاصة:</strong> هنا جوهر السوق. الجامعات الخاصة تتعاقد مع وكلاء وتدفع لهم عمولة، ولذا يستطيع الوكيل المعتمد منحك خصماً حقيقياً من الرسم المعلن — راجع <a href="/article/private-universities-turkey-2026">دليل الجامعات الخاصة</a> لتعرف الرسوم المعلنة أولاً.</li><li><strong>اللوجستيات:</strong> استقبال من المطار، سكن مؤقت، فتح حساب، خط هاتف — خدمة مريحة لمن لا يعرف البلد، وكلها أشياء يمكن فعلها ذاتياً بكلفة أقل.</li><li><strong>الأوراق والترجمة:</strong> وساطة مع مكاتب النوتر والترجمة المحلفة — مفيدة لضيق الوقت، وليست حكراً عليهم.</li><li><strong>المتابعة:</strong> تذكيرك بمواعيد التسجيل والامتحانات والتجديد.</li></ul><h2>متى يكون الوكيل قيمة حقيقية؟</h2><ul><li>تريد جامعة <strong>خاصة</strong> وخصم الوكيل المعتمد أدنى من الرسم المعلن على موقع الجامعة — تحقّقت من الرقمين بنفسك.</li><li>لا تعرف التركية ولا أحد لك في تركيا، وقيمة وقتك أعلى من رسم الخدمة.</li><li>حالتك معقدة (استكمال دراسة، معادلات) وتريد من رتّب مثلها من قبل — مع بقاء القرار للجامعة كما تشرح صفحة <a href="/article/continue-studies-turkey-2026">استكمال الدراسة</a>.</li></ul><h2>علامات الخطر — إن رأيت واحدة فتوقف</h2><ol><li><strong>«قبول مضمون» في جامعة حكومية أو منحة:</strong> لا أحد يملك قرار الحكومية ولا المنحة. هذا وعد بما لا يُملك.</li><li><strong>«نستخرج لك إقامة» كخدمة مستقلة:</strong> الإقامة طلبك أنت عبر e-ikamet بشروط القانون — <a href="/article/student-residence-permit-2026">دليل إقامة الطالب</a> يريك أنها ليست سراً يُشترى.</li><li><strong>حجز أصول أوراقك</strong> (جواز، شهادات) عندهم «حتى إتمام الملف».</li><li><strong>رسوم غامضة</strong> تظهر بعد التوقيع، أو خصم «لفترة محدودة» يضغطك على قرار اليوم.</li><li><strong>لا عقد مكتوباً</strong> يسمّي الخدمة والرسم وسياسة الاسترداد إن رُفض القبول أو التأشيرة.</li></ol><h2>كيف تتحقق قبل الدفع — خمس دقائق تكفي</h2><ul><li>اطلب الاسم القانوني ورقم السجل التجاري وتحقق أن الكيان قائم فعلاً.</li><li>اطلب إثبات اعتماد الوكيل لدى الجامعة التي يعرضها — الجامعات تنشر وكلاءها المعتمدين أو تؤكدهم بمراسلة القبول الدولي مباشرة.</li><li>قارن الرسم الذي يعرضه بالرسم المعلن على موقع الجامعة نفسها.</li><li>ابحث عن مراجعات مستقلة خارج صفحات الشركة نفسها.</li><li>عقد مكتوب أو لا صفقة — يسمّي كل خدمة ورسمها وحالة الاسترداد.</li></ul><p>وابدأ دائماً من الصورة الكاملة قبل أي وسيط: <a href="/article/study-in-turkey-universities-2026">دليل الدراسة في تركيا</a> ثم <a href="/article/after-yos-turkey-university-tercih-application-registration-2026">مسار التقديم بعد اليوس</a> — فمن عرف الطريق قيّم الدليل.</p>',
        ARRAY['حدّد أولاً: حكومية أم خاصة أم منحة؟ فالمجاني الرسمي يغطي الحكومية والمنح كاملاً.', 'اعرف الرسم المعلن للبرنامج من موقع الجامعة قبل سماع أي عرض.', 'قارن عرض الوكيل بالرسم المعلن — القيمة الحقيقية هي الفرق، لا الكلام.', 'تحقق من السجل التجاري واعتماد الوكيل لدى الجامعة.', 'عقد مكتوب يسمّي الخدمات والرسوم وسياسة الاسترداد — قبل أي دفعة.', 'لا تسلّم أصل جواز أو شهادة لأحد — الأصول تُعرض ولا تُرهن.']::text[],
        ARRAY['عمولة الوكيل المعتمد تدفعها الجامعة الخاصة — لذا قد يكون خصمه حقيقياً؛ تحقق بالرقمين.', '«قبول مضمون» في حكومية أو منحة = وعد بما لا يُملك، فاقطع الاتصال.', 'التقديم على منحة الحكومة التركية مجاني بالكامل — أي رسم عليه احتيال.', 'YÖK Atlas يريك البرامج والجامعات مجاناً قبل أي مستشار.', 'ضغط «الخصم ينتهي اليوم» أسلوب بيع لا حقيقة أكاديمية.', 'الإقامة والتأشيرة طلبك أنت بشروط القانون — لا «تُستخرج» شراءً.']::text[],
        ARRAY['عقد مكتوب يسمّي الخدمة والرسم وسياسة الاسترداد', 'إثبات اعتماد الوكيل لدى الجامعة المعروضة', 'الرسم المعلن للبرنامج من موقع الجامعة (للمقارنة)', 'سجل الشركة التجاري واسمها القانوني']::text[],
        'رسوم هذه الشركات غير منظّمة بتعرفة رسمية — تتفاوت من خدمة رمزية إلى مبالغ كبيرة بلا فرق جودة يبرّرها. المسطرة الوحيدة: ما الذي تدفعه فوق الرسم المعلن للجامعة، ومقابل أي خدمة مسماة في عقد مكتوب.',
        'من وعدك بقبول جامعة حكومية أو منحة حكومية «مضموناً» فقد وعدك بقرار لا يملكه أحد خارج تلك المؤسسات. وسلّم صوراً لا أصولاً: جوازك وشهاداتك لا تُرهن عند وسيط مهما بدا موثوقاً.',
        'بوابات القبول المباشر للجامعات التركية الحكومية والخاصة؛ ومنصة YÖK Atlas لاستكشاف البرامج؛ وبوابة منحة الحكومة التركية Türkiye Bursları (التقديم مجاني رسمياً)؛ ونماذج تعاقد الجامعات الخاصة مع وكلاء قبول معتمدين تنشرها الجامعات',
        ARRAY['شركات الخدمات الطلابية', 'القبول الجامعي', 'الدراسة والتعليم', 'حماية المستهلك', 'دليل']::text[],
        'الدراسة والتعليم',
        'approved',
        'شركات الخدمات الطلابية في تركيا: متى تفيد وكيف تتحقق منها',
        'لا نرشّح شركة ولا نذمّها — نعطيك المسطرة: ما المجاني رسمياً (الحكومية والمنح وYÖK Atlas)، أين قيمة الوكيل الحقيقية (خصوم الخاصة)، وخمس علامات خطر تكشف المبالِغ قبل أن تدفع.',
        CURRENT_DATE)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title, intro = EXCLUDED.intro, details = EXCLUDED.details,
    steps = EXCLUDED.steps, tips = EXCLUDED.tips, documents = EXCLUDED.documents,
    fees = EXCLUDED.fees, warning = EXCLUDED.warning, source = EXCLUDED.source,
    tags = EXCLUDED.tags, category = EXCLUDED.category, status = EXCLUDED.status,
    seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description,
    last_update = EXCLUDED.last_update;

-- ─── student-benefits-discounts-turkey-2026 ───
INSERT INTO articles (id, slug, title, intro, details, steps, tips, documents, fees, warning, source, tags, category, status, seo_title, seo_description, last_update)
VALUES ('student-benefits-discounts-turkey-2026',
        'student-benefits-discounts-turkey-2026',
        'خصومات وبطاقات الطالب في تركيا 2026: المواصلات والتأمين والمتاحف والسكن — عُدّة الطالب كاملة',
        'صفة «طالب» في تركيا ليست شعاراً — هي حزمة خصومات وحقوق حقيقية تبدأ من نصف أجرة المواصلات ولا تنتهي عند نافذة تأمين حكومي لا تتكرر. المشكلة أن أحداً لا يجمعها لك في مكان واحد، وأن نصفها نوافذ تُفتح مرة وتُغلق. هذه الصفحة تجمع العُدّة كاملة: بطاقة المواصلات الطلابية، ونافذة GSS الثلاثية، وسكن KYK المدعوم، وحق العمل الجزئي، والوثائق المجانية — بالآلية الرسمية لكلٍّ منها، لا بأرقام تتقادم قبل أن تقرأها.',
        '<h2>1) بطاقة المواصلات الطلابية — أثقل خصم في حياتك اليومية</h2><p>كل مدينة كبرى تصدر نسخة طلابية من بطاقة مواصلاتها (في إسطنبول: İstanbulkart بصفة طالب، ولها نظائر في أنقرة وإزمير وبورصة وغيرها): اشتراكات وتعرفة مخفّضة بوضوح عن العادية. التفعيل يكون بإثبات الصفة الطلابية — وثيقة الطالب أو بيانات قيدك الجامعي — عبر قنوات بلدية مدينتك (تطبيقها الرسمي أو مراكز البطاقات)، ويُجدَّد سنوياً ما دام قيدك قائماً. استخرج وثيقة الطالب في دقيقة من <a href="/article/transcript-edevlet">e-Devlet</a>.</p><h2>2) نافذة GSS الثلاثية — الخصم الذي لا يتكرر</h2><p>للطالب الأجنبي حقّ التسجيل الاختياري في التأمين الصحي العام (GSS) خلال <strong>الأشهر الثلاثة الأولى من أول قيد جامعي</strong> — بقسط أوفر من التأمين الخاص عادةً وبتغطية أوسع. من فوّت النافذة بقي على الخاص طوال دراسته. التفاصيل في <a href="/article/sgk-gss-health-insurance-turkey-2026">دليل SGK وGSS</a> وموقعها من ملف الإقامة في <a href="/article/student-residence-permit-2026">دليل إقامة الطالب</a>.</p><h2>3) سكن KYK الحكومي — الأرخص إن أدركته</h2><p>مساكن وزارة الشباب والرياضة أدنى خيارات السكن كلفةً، والتقديم موسمي إلكتروني — الشروط والأولويات والبدائل كلها في <a href="/article/kyk-yurt-devlet-yabanci-suriyeli-ogrenciler-2026">دليل سكن KYK للطلاب الأجانب</a>، ولمن اختار الشقق: <a href="/article/renting-house">دليل الاستئجار وفخاخه</a>.</p><h2>4) العمل الجزئي — حق بنص القانون لا تساهلاً</h2><p>طالب البكالوريوس بعد سنته الأولى يعمل بدوام جزئي بإذن، وطلاب الدراسات العليا أوسع حقاً — الشروط والحدود في <a href="/article/work-permit-students">دليل عمل الطلاب الأجانب</a>. (تذكير: الحق للقيد النظامي — لا يشمل <a href="/article/open-education-turkey-2026">التعليم المفتوح</a>.)</p><h2>5) المتاحف والثقافة</h2><p>لبطاقة المتاحف (Müzekart) فئات وأسعار تفضيلية للمقيمين تتغير تعرفتها دورياً — انظر <a href="/article/travel-muzekart">صفحة MüzeKart</a> وتحقق من الفئة الطلابية عند الشراء من المنافذ الرسمية. وكثير من المسارح ودور العرض والفعاليات البلدية تعتمد تعرفة طلابية ببطاقتك الجامعية — اسأل قبل الدفع دائماً؛ أسوأ ما يحدث أن يقال لا.</p><h2>6) السفر والاتصالات والاشتراكات</h2><p>الخطوط الجوية التركية وشركات نقل أخرى تعتمد فئات أسعار طلابية بشروط (عمر، وثيقة طالب، خطوط محددة) — والعروض تتبدل، فالقاعدة: ابحث عن خيار «طالب/Öğrenci» في قناة الحجز الرسمية وتحقق من شرطه قبل الشراء، ولا تشترِ «تفعيل خصم» من وسيط. الأمر نفسه في باقات الاتصالات وخدمات البرمجيات والاشتراكات: الفئة الطلابية موجودة غالباً وتُفعَّل ببريدك الجامعي أو وثيقتك — من القناة الرسمية حصراً.</p><h2>7) وثائقك — مجانية ولا تحتاج أحداً</h2><p>وثيقة الطالب وكشف الدرجات برمز تحقق من <a href="/article/transcript-edevlet">e-Devlet مجاناً</a> — لا تدفع لوسيط ثمن ورقة تملكها بنقرة. والمنح طبقة فوق كل ما سبق: <a href="/article/scholarship-turkey-overview">خريطة المنح في تركيا</a>.</p><h2>أسئلة متكرّرة</h2><h3>هل تنطبق الخصومات على طالب التعليم المفتوح؟</h3><p>بعضها مرتبط بوثيقة طالب سارية (تصدر لطلاب المفتوح أيضاً) وبعضها بحقوق لا يؤسسها المفتوح أصلاً كالعمل الطلابي — راجع <a href="/article/open-education-turkey-2026">حدود المفتوح بصراحة</a>.</p><h3>أنا على الحماية المؤقتة وأدرس — ما الذي يخصني؟</h3><p>صحتك مغطاة بنظام الحماية المؤقتة نفسه لا بنافذة GSS الطلابية، وبطاقة المواصلات الطلابية ووثائق e-Devlet تخصك كأي طالب مقيّد.</p><h3>وثيقة الطالب انتهى مفعولها عند جهة الخصم — ماذا أفعل؟</h3><p>الجهات تريدها حديثة العهد عادة — استخرج نسخة جديدة من e-Devlet لحظتها؛ الاستخراج فوري ومجاني ولا عدد لمراته.</p>',
        ARRAY['فعّل الصفة الطلابية في بطاقة مواصلات مدينتك فور التسجيل — أثقل خصم يومي.', 'خلال أول 3 أشهر من قيدك: اسأل SGK عن التسجيل في GSS قبل شراء تأمين خاص.', 'قدّم لسكن KYK في موسمه الإلكتروني إن أردت أدنى كلفة سكن.', 'استخرج وثيقة الطالب من e-Devlet واحملها في هاتفك — مفتاح كل خصم.', 'ابحث عن فئة «Öğrenci» في كل حجز واشتراك — من القناة الرسمية حصراً.', 'بعد سنتك الأولى: قيّم حاجتك للعمل الجزئي بإذن وفق دليل عمل الطلاب.']::text[],
        ARRAY['نافذة GSS لا تتكرر — ثلاثة أشهر من أول قيد ثم تُغلق طوال الدراسة.', 'كل خصم مصدره بطاقتك أو وثيقتك عبر القناة الرسمية — «تفعيل الخصومات» المدفوع احتيال.', 'وثيقة الطالب تُستخرج مجاناً بلا حد — لا تدفع لأحد ثمنها.', 'العروض التجارية (طيران، اشتراكات) تتبدل — تحقق من الشرط عند الشراء لا من مقال.', 'حامل الحماية المؤقتة: صحتك بنظام الحماية لا بنافذة GSS الطلابية.', 'اسأل عن تعرفة طلابية قبل كل دفع ثقافي — أسوأ الاحتمالات كلمة لا.']::text[],
        ARRAY['وثيقة الطالب (Öğrenci Belgesi) من e-Devlet — حديثة العهد', 'بطاقة مواصلات المدينة مفعّلة بالصفة الطلابية', 'جواز/بطاقة إقامة سارية لمعاملات التسجيل', 'البريد الجامعي لتفعيل العروض الرقمية الطلابية']::text[],
        'تعرفات المواصلات الطلابية وأقساط GSS ورسوم KYK تُحدَّث دورياً وتختلف بالمدينة والحالة — لا نثبت أرقاماً؛ القاعدة الثابتة أن الفئة الطلابية أدنى بوضوح من العادية في كل بند، والرقم الجاري تأخذه من القناة الرسمية لكل جهة.',
        'كل خصم طريقه القناة الرسمية ببطاقتك أو وثيقتك — من يبيعك «تفعيل خصومات الطلاب» أو «بطاقة مخفضة» من خارجها يبيعك مخالفة قد تكلفك البطاقة نفسها. ونافذة GSS الثلاثية موعد لا يرحم: سجّل أو اخسرها لسنوات دراستك كلها.',
        'أنظمة البطاقات الطلابية لدى بلديات المدن الكبرى (إسطنبول وأنقرة وإزمير وغيرها)؛ ونافذة التسجيل الاختياري للطلاب الأجانب في GSS خلال ثلاثة أشهر من أول قيد (قانون 5510 — راجع مديرية SGK)؛ ومساكن KYGM التابعة لوزارة الشباب والرياضة؛ وحق العمل الطلابي في قانون العمالة الدولية 6735',
        ARRAY['خصومات الطلاب', 'بطاقة الطالب', 'الدراسة والتعليم', 'GSS', 'دليل', '2026']::text[],
        'الدراسة والتعليم',
        'approved',
        'خصومات الطالب في تركيا: المواصلات والتأمين والسكن — العُدّة كاملة',
        'نصف أجرة المواصلات، نافذة GSS التي لا تتكرر، سكن KYK، العمل الجزئي بنص القانون، ووثائق مجانية من e-Devlet — عُدّة الطالب في تركيا مجموعة لأول مرة في صفحة واحدة، بالآلية الرسمية لا بأرقام تتقادم.',
        CURRENT_DATE)
