INSERT INTO articles (id, slug, title, intro, details, steps, tips, documents, fees, warning, source, tags, category, status, seo_title, seo_description, last_update)
VALUES ('turkey-study-visa-syrians-2026',
        'turkey-study-visa-syrians-2026',
        'تأشيرة الدراسة التركية للسوريين 2026: الملف الكامل بأقسامه الأربعة — وشرطا التقديم من دمشق',
        'تأشيرة الطالب هي الباب القانوني الوحيد للقادم للدراسة — الدخول بتأشيرة سياحية ثم «التدبير من الداخل» طريق يتعثر. وللسوريين خصوصية لا يشرحها أحد بدقة: شرطان يحددان من يقدّم من دمشق ومن لا طريق له إلا مكتب بيروت. هذا الدليل يبني ملفك بأقسامه الأربعة — الجامعي والرسمي والمالي واللوجستي — ويقول بصراحة ما الذي يقوّي الطلب، ولماذا تقدّم قبل السفر بشهرين لا بأسبوعين، وماذا تسأل عن سياسة استرداد رسوم الجامعة قبل أن تدفعها.',
        '<div style="background:#ecfdf5;border:2px solid #10b981;border-radius:12px;padding:18px 22px;margin:0 0 20px;"><p style="margin:0 0 10px;font-size:17px;"><strong>القاعدة الأولى: طالبٌ لا سائح</strong></p><p style="margin:0;">القادم للدراسة يتقدم لتأشيرة <strong>طالب</strong> من ممثلية تركيا المختصة ببلده. وقدّم <strong>قبل موعد سفرك بشهر ونصف إلى شهرين</strong> — مدد البت تتفاوت بالممثلية والموسم، ولا وعد مدةٍ يُبنى عليه حجز ولا التزام.</p></div><h2>ملف التأشيرة بأقسامه الأربعة</h2><h3>أولاً: القسم الجامعي</h3><ul><li><strong>رسالة قبول من جامعة تركية</strong> مع رقم YÖK ID بصيغة XX-XXX-XX — القبول النهائي لا المبدئي وحده.</li><li>أصل شهادة الدبلوم/الثانوية أو طبق الأصل المصدق.</li></ul><h3>ثانياً: القسم الرسمي والشخصي</h3><ul><li>جواز سفر ساري <strong>6 أشهر بعد تاريخ المغادرة</strong> + صفحتان فارغتان.</li><li>صورة بيومترية (40×55 مم) بخلفية بيضاء، حديثة خلال آخر 6 أشهر.</li><li>استمارة طلب التأشيرة موقّعة.</li><li>سجلّ عدلي مترجم للتركية من مترجم محلّف (للبالغين).</li></ul><h3>ثالثاً: القسم المالي</h3><ul><li>كشف حساب بنكي أصلي مختوم + بيان دخل من جهة العمل — باسمك أو باسم كفيلك.</li><li>إن كان المموّل كفيلاً (الأب عادة): تعهد كفالة مكتوب + إثبات هويته، مترجمة مصدقة إن طُلبت.</li><li>المطلوب إثبات مقدرة تغطي الرسوم والمعيشة طوال الدراسة — لا رقم رسمياً موحداً معلناً، فالمعيار كفاية المبلغ واتساقه مع مدة برنامجك.</li></ul><h3>رابعاً: القسم اللوجستي</h3><ul><li>حجز فندقي + تذكرة طيران (قابلة للاسترداد ما أمكن — انظر التحذير أدناه).</li></ul><p>تُقبَل الترجمات المُحلَّفة باللغة التركية حصراً.</p><h2>حالات السوريين الخاصة — الشرطان ومكتب بيروت</h2><ol><li>الطلّاب السوريون الذين لديهم <strong>تسجيل قديم في تركيا</strong> (نشط أو غير نشط) يمكنهم التقديم على فيزا الطالب من سوريا.</li><li>السوريون الحاصلون على وضع «الحماية المؤقتة» <strong>وتخلّوا عنه وعادوا إلى بلدهم</strong>، يمكنهم التقديم مجدّداً بشرط قبول نهائي من جامعة.</li><li>من لا يستوفي أحد الشرطين أعلاه، يمكنه التقديم <strong>فقط من مكتب بيروت</strong>.</li></ol><p>الجهة المعتمدة لتقديم الطلبات في سوريا: مكتب <strong>Visa FG</strong> (sy.visafg.com). والرسم الرسمي كان <strong>145 دولاراً أمريكياً</strong> عند آخر تحقق — تأكد من الرقم الجاري عند الحجز فالتعرفات تُحدَّث.</p><h2>وثائق تُحسّن فرص القبول</h2><ul><li>إثبات نسبية مع أقارب من الدرجة الأولى مقيمين في تركيا (الأم، الأب، الأخ، الأخت).</li><li>نسخ صفحات جواز السفر القديم إن سبق وزرت تركيا.</li><li>إثبات ملكية عقار في تركيا إن وُجد.</li><li>دعوة من شخص مقيم في تركيا مع وثائق إقامته ودعمه المالي.</li></ul><h2>المقابلة والرفض — والسؤال المالي الذي يسبق كل دفع</h2><p>قد تُطلب مقابلة قصيرة في الممثلية: أسئلتها المعتادة عن برنامجك وتمويلك وخطتك بعد التخرج — أجوبة متسقة مع ملفك تكفي، والتناقض بين قولك وأوراقك أخطر من أي نقص. وإن رُفضت التأشيرة فرسوم الجامعة المدفوعة تخضع <strong>لسياسة الاسترداد الخاصة بكل جامعة</strong> — بعضها يعيد وبعضها لا: <strong>اسأل عن سياسة الاسترداد كتابةً قبل دفع أي رسم</strong>، فهذا السؤال أرخص درس في الملف كله.</p><h2>وبعد التأشيرة؟</h2><p>التأشيرة تُدخلك — والإقامة تُبقيك: فور وصولك تبدأ مهلة تقديمك لإقامة الطالب عبر e-ikamet. الرحلة كاملة في <a href="/article/student-residence-permit-2026"><strong>دليل إقامة الطالب من الطلب إلى التجديد ←</strong></a> — ولتمويل دراستك: <a href="/article/scholarship-turkiye-burslari">منحة الحكومة التركية</a>، وللصورة الكاملة: <a href="/article/study-in-turkey-universities-2026">دليل الدراسة في تركيا</a>.</p>',
        ARRAY['أمّن القبول النهائي من الجامعة (برقم YÖK ID) — أساس الملف كله.', 'حدّد مسارك: أحد الشرطين يتيح التقديم من سوريا عبر Visa FG، وإلا فمكتب بيروت.', 'اجمع الملف بأقسامه الأربعة: الجامعي والرسمي والمالي واللوجستي.', 'ترجمة محلفة بالتركية لكل وثيقة تتطلبها — حصراً.', 'اسأل الجامعة كتابةً عن سياسة استرداد الرسوم عند رفض التأشيرة — قبل الدفع.', 'قدّم قبل السفر بشهر ونصف إلى شهرين ولا تبنِ حجزاً على وعد مدة.', 'بعد الوصول: ملف إقامة الطالب عبر e-ikamet قبل انتهاء مهلتك — فوراً لا آجلاً.']::text[],
        ARRAY['طالبٌ لا سائح — الدخول السياحي «للتدبير» يعقّد ملفك الأول كله.', 'القبول المبدئي لا يكفي وحده — النهائي برقم YÖK ID هو المعتمد.', 'التناقض بين أجوبة المقابلة والأوراق أخطر من أي نقص فيها.', 'تذكرة قابلة للاسترداد وسؤال الاسترداد المكتوب — تأمينك الحقيقي ضد الرفض.', 'الرسم بالدولار يُحدَّث — تحقق من الرقم الجاري عند الحجز.', 'شرطا التقديم من سوريا حرفيان — لا «استثناءات» يبيعها وسيط.']::text[],
        ARRAY['رسالة قبول نهائي برقم YÖK ID + أصل الشهادة الثانوية', 'جواز ساري 6 أشهر بعد المغادرة + صفحتان فارغتان + صورة بيومترية حديثة', 'سجل عدلي مترجم ترجمة محلفة + استمارة موقعة', 'كشف حساب مختوم + بيان دخل (منك أو من كفيلك مع تعهده)', 'حجز فندقي وتذكرة طيران']::text[],
        'رسم التأشيرة يُسدَّد بالدولار وفق تعرفة تُحدَّث (كان 145 دولاراً عند آخر تحقق) — والكلفة الحقيقية للملف تشمل الترجمة المحلفة والتصديق وأجور مكتب التقديم؛ تحقق من الأرقام الجارية عند الحجز ولا تدفع لجامعة قبل معرفة سياسة الاسترداد.',
        'لا تدفع رسوم جامعة قبل سؤال مكتوب عن سياسة الاسترداد عند رفض التأشيرة — بعض الجامعات لا يعيد شيئاً. ولا تدخل بتأشيرة سياحية «لتدبّر» الدراسة من الداخل. وشرطا التقديم من سوريا حرفيان لا يتسعان لوعود الوسطاء.',
        'قواعد تأشيرات الدراسة عبر ممثليات تركيا وبوابة konsolosluk.gov.tr؛ ومكتب Visa FG المعتمد للطلبات في سوريا (sy.visafg.com) وشرطا التقديم من دمشق المعمول بهما؛ ورقم القبول الجامعي YÖK ID من منظومة التعليم العالي التركية',
        ARRAY['تأشيرة الدراسة', 'فيزا الطالب', 'السوريون', 'الدراسة والتعليم', 'دليل', '2026']::text[],
        'الدراسة والتعليم',
        'approved',
        'تأشيرة الدراسة للسوريين: الملف الكامل وشرطا التقديم من دمشق',
        'ملف تأشيرة الطالب بأقسامه الأربعة، والشرطان اللذان يحددان من يقدّم من سوريا عبر Visa FG ومن طريقه مكتب بيروت، وسؤال الاسترداد الذي يسبق كل دفع — بصياغة من يعرف الطريق لا من يبيعه.',
        CURRENT_DATE)
ON CONFLICT (id) DO UPDATE SET
    title = EXCLUDED.title, intro = EXCLUDED.intro, details = EXCLUDED.details,
    steps = EXCLUDED.steps, tips = EXCLUDED.tips, documents = EXCLUDED.documents,
    fees = EXCLUDED.fees, warning = EXCLUDED.warning, source = EXCLUDED.source,
    tags = EXCLUDED.tags, category = EXCLUDED.category, status = EXCLUDED.status,
    seo_title = EXCLUDED.seo_title, seo_description = EXCLUDED.seo_description,
    last_update = EXCLUDED.last_update;

-- المحور: استبدال أرقام الرواتب المتقادمة بالآلية (بإبرة مضبوطة)
UPDATE articles
   SET details = replace(details, '<li><strong>راتب شهري:</strong> بكالوريوس 3,500 ليرة / ماجستير 5,000 ليرة / دكتوراه 7,000 ليرة</li>', '<li><strong>راتب شهري:</strong> بحسب المرحلة، ويُحدَّث سنوياً — الأرقام الجارية في <a href="/article/scholarship-turkiye-burslari">دليل المنحة الكامل</a></li>'),
       last_update = CURRENT_DATE
 WHERE slug = 'study-in-turkey-universities-2026'
   AND position('<li><strong>راتب شهري:</strong> بكالوريوس 3,500 ليرة / ماجستير 5,000 ليرة / دكتوراه 7,000 ليرة</li>' in details) > 0;

-- المحور: قسم قراءة التصنيفات (محروس)
UPDATE articles
   SET details = details || '<h2>ترتيب الجامعات التركية: كيف تقرأه دون أن يخدعك</h2><p>لا يوجد «ترتيب رسمي» واحد: التصنيفات العالمية (THE وQS وURAP وWebometrics) تقيس أشياء مختلفة وتتبدل مراكزها سنوياً — فأي جدول أرقام تقرؤه اليوم يتقادم غداً. الثابت عبر السنوات والتصنيفات أن مجموعة جامعات تتصدر باستمرار: حكومياً الشرق الأوسط التقنية (ODTÜ) وإسطنبول التقنية (İTÜ) وبوغازيتشي وهاجت تبه، وخاصّاً كوتش وبيلكنت وسابانجي. وللاختيار العملي استخدم منصة <strong>YÖK Atlas</strong> الرسمية: تقارن البرامج بمعدلات القبول الفعلية لا بدعاية أحد. وتفاصيل الخاصة ورسومها في <a href="/article/private-universities-turkey-2026">دليل الجامعات الخاصة</a>.</p>', last_update = CURRENT_DATE
 WHERE slug = 'study-in-turkey-universities-2026'
   AND position('كيف تقرأه دون أن يخدعك' in details) = 0;

-- صفحة KYK: قسم بقية خيارات السكن (محروس)
UPDATE articles
   SET details = details || '<h2>ليس اليورت وحده: بقية خيارات السكن</h2><p>إن فاتك مقعد KYK أو لم يناسبك نمطه، فالخيارات التالية بترتيب الكلفة عادة: <strong>المساكن الخاصة (Özel Yurt / Apart)</strong> بإشراف تجاري وأسعار تتفاوت بالمدينة والخدمات — قارن عقدها وما يشمله قبل الحجز؛ و<strong>سكن الجامعات الخاصة</strong> داخل حرمها أو قربه لمن يدرس فيها؛ و<strong>الشقق المشتركة</strong> وهي الأوسع حرية والأكثر التزامات — عقد إيجار رسمي وإثبات عنوان وفواتير، وتفاصيلها وفخاخها في <a href="/article/renting-house">دليل استئجار منزل في تركيا</a>. وأياً كان خيارك فإثبات السكن الموثق ركن في ملف <a href="/article/student-residence-permit-2026">إقامة الطالب</a>، وبقية خصومات حياتك اليومية مجموعة في <a href="/article/student-benefits-discounts-turkey-2026">عُدّة الطالب كاملة</a>.</p>', last_update = CURRENT_DATE
 WHERE slug = 'kyk-yurt-devlet-yabanci-suriyeli-ogrenciler-2026'
   AND position('بقية خيارات السكن' in details) = 0;

SET session_replication_role = 'origin';

-- ═══════════════════════════════════════════════════════════════════════════
DO $check$
DECLARE n int;
BEGIN
    SELECT count(*) INTO n FROM articles
     WHERE slug IN ('open-education-turkey-2026', 'continue-studies-turkey-2026',
                    'student-services-companies-turkey', 'student-benefits-discounts-turkey-2026')
       AND status = 'approved' AND length(details) > 3000;
    IF n <> 4 THEN RAISE EXCEPTION 'expected 4 new approved guides, found %', n; END IF;

    SELECT count(*) INTO n FROM articles
     WHERE slug IN ('open-education-turkey-2026', 'continue-studies-turkey-2026',
                    'student-services-companies-turkey', 'student-benefits-discounts-turkey-2026',
                    'turkey-study-visa-syrians-2026');
    IF n <> 5 THEN RAISE EXCEPTION 'duplicate slug leak: % rows', n; END IF;

    SELECT count(*) INTO n FROM articles
     WHERE slug = 'open-education-turkey-2026'
       AND position('لا تُصدر' in details) > 0 AND position('إقامة طالب' in details) > 0;
    IF n <> 1 THEN RAISE EXCEPTION 'open-education boundary missing'; END IF;

    SELECT count(*) INTO n FROM articles
     WHERE slug = 'continue-studies-turkey-2026' AND position('Ek Madde 2' in details) > 0;
    IF n <> 1 THEN RAISE EXCEPTION 'Ek Madde 2 anchor missing'; END IF;

    SELECT count(*) INTO n FROM articles
     WHERE slug = 'turkey-study-visa-syrians-2026'
       AND position('فقط من مكتب بيروت' in details) > 0
       AND position('سياسة الاسترداد' in details) > 0
       AND length(details) > 3000;
    IF n <> 1 THEN RAISE EXCEPTION 'visa rebuild lost the Beirut facts or is thin'; END IF;

    SELECT count(*) INTO n FROM articles
     WHERE slug = 'study-in-turkey-universities-2026'
       AND position('3,500 ليرة' in details) = 0
       AND position('كيف تقرأه دون أن يخدعك' in details) > 0;
    IF n <> 1 THEN RAISE EXCEPTION 'hub fix did not land'; END IF;

    SELECT count(*) INTO n FROM articles
     WHERE slug = 'kyk-yurt-devlet-yabanci-suriyeli-ogrenciler-2026'
       AND position('بقية خيارات السكن' in details) > 0;
    IF n <> 1 THEN RAISE EXCEPTION 'KYK append did not land'; END IF;
END
$check$;

SELECT slug AS الصفحة, length(details) AS الحجم, status AS الحالة, last_update AS آخر_تحديث
  FROM articles
 WHERE slug IN ('open-education-turkey-2026', 'continue-studies-turkey-2026',
                'student-services-companies-turkey', 'student-benefits-discounts-turkey-2026',
                'turkey-study-visa-syrians-2026', 'study-in-turkey-universities-2026',
                'kyk-yurt-devlet-yabanci-suriyeli-ogrenciler-2026')
 ORDER BY slug;
